// Simpan insights IG ke post_metrics. Response: {id, insights:{data:[{name,values}]}}
// Tidak butuh pairing: media id ada di response → SQL pakai subquery external_id.
const g = (arr, name) => {
  const m = arr.find(x => x.name === name);
  if (!m || !m.values || !m.values[0]) return null;
  return Number(m.values[0].value || 0);
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const arr = (j.insights && j.insights.data) || [];
  if (!j.id || !arr.length) continue;
  const esc = s => String(s).replace(/'/g, "''");
  const v = x => (x === null || x === undefined || Number.isNaN(Number(x)) ? 'NULL' : Number(x));
  const sql = `INSERT INTO post_metrics (post_id, source, plays, likes, comments, saves, shares)
    SELECT p.id, 'ig', ${v(g(arr, 'plays'))}, ${v(g(arr, 'likes'))}, ${v(g(arr, 'comments'))}, ${v(g(arr, 'saved'))}, ${v(g(arr, 'shares'))}
    FROM posts p WHERE p.external_id = '${esc(j.id)}'
    ON CONFLICT (post_id, source)
    DO UPDATE SET plays = EXCLUDED.plays, likes = EXCLUDED.likes, comments = EXCLUDED.comments,
                  saves = EXCLUDED.saves, shares = EXCLUDED.shares, fetched_at = now();`;
  out.push({ json: { sql } });
}
return out.length ? out : [{ json: { sql: 'SELECT 1', skipped: true } }];

// Susun permintaan LLM — AI analis harian dengan mindset operator bisnis.
const raw = $json.metrics || {};
const metrics = typeof raw === 'string' ? JSON.parse(raw) : raw;
const hariIni = new Date().toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Asia/Jakarta' });

const system = `Kamu otak analitik bisnis afiliasi media pendek (TikTok + IG Reels; Shopee ID + SaaS EN).
Berpikirlah seperti investor-operand mandiri yang membangun dari nol: data dulu, ego belakangan.
Prinsip:
1. Diagnosis sebelum resep — sebut metrik yang bergerak + penyebab paling mungkin dari DATA.
2. Saat pendapatan turun, JANGAN ubah semua hal — potong kerugian terbesar, gandakan pemenang terbukti (Pareto 80/20).
3. Uji kecil, umpan balik cepat, scale yang menang.
4. Setiap perubahan butuh dampak yang diharapkan + cara memverifikasi minggu depan.
5. Jujur — kalau data terlalu tipis, bilang begitu dan sarankan kesabaran + uji kecil.
Keluaran HANYA JSON ketat.`;

const user = `Hari ini: ${hariIni}. Data pipeline invest-nyawit.

DATA:
${JSON.stringify(metrics)}

Aturan keputusan:
- income_7d turun >= 25% vs income_prev_7d, ATAU drop_rate_7d >= 40% → severity=\"decline\", analisis penuh WAJIB (diagnosis akar masalah dari data: platform mana, jam berapa, produk mana, CR/AOV).
- ${hariIni === 'Sunday' ? 'Hari ini Minggu → ulasan mingguan penuh, severity=\"weekly\".' : 'Kalau tidak ada penurunan berarti → skip=true (tidak usul apa-apa, jangan spam owner).'}
- Jangan mengarang metrik yang tidak ada di DATA.

Keluarkan HANYA JSON dengan skema:
{
  \"skip\": false,
  \"severity\": \"weekly\",
  \"analysis\": \"ringkasan 2-4 kalimat: apa naik/turun dan mengapa (berbasis angka)\",
  \"diagnosis\": \"akar masalah dari data (kosongkan kalau tidak ada masalah)\",
  \"keep\": [\"elemen terbukti yang dipertahankan\"],
  \"stop\": [\"yang dihentikan/diubah\"],
  \"changes\": {
    \"keywords_id\": [\"5-8 kata kunci produk Shopee, impulse-buy 15rb-150rb\"],
    \"hook_style\": \"gaya hook unggulan, maks 8 kata\",
    \"tone\": \"nada penulisan singkat\",
    \"min_score\": 70,
    \"quota\": { \"id\": 3, \"en\": 2 }
  },
  \"hypotheses\": [\"uji A/B konkret + cara verifikasi\"],
  \"expected_impact\": \"perkiraan dampak dalam angka/bulan\",
  \"health\": 75
}

Aturan angka: min_score 50-95; quota.id 0-6; quota.en 0-4; health 0-100.`;

return {
  json: {
    endpoint: ($env.LLM_BASE_URL || '').replace(/\/$/, '') + '/chat/completions',
    auth: 'Bearer ' + ($env.LLM_API_KEY || ''),
    request: {
      model: $env.LLM_MODEL,
      temperature: 0.3,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ]
    }
  }
};

// Parse + clamp hasil analis. skip=true → tidak usul apa-apa (sehat).
let content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
content = content.replace(/^```(json)?\s*/i, '').replace(/```\s*$/, '').trim();
const m = content.match(/\{[\s\S]*\}/);
if (!m) throw new Error('LLM analis tidak menghasilkan JSON: ' + content.slice(0, 300));
const s = JSON.parse(m[0]);

if (s.skip === true) {
  return { json: { skip: true } };
}

const clamp = (v, lo, hi, dflt) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return dflt;
  return Math.min(hi, Math.max(lo, n));
};
const strArr = (a, max) => (Array.isArray(a) ? a.map(x => String(x).trim()).filter(Boolean).slice(0, max) : []);

const c = (s.changes && typeof s.changes === 'object') ? s.changes : {};
const q = (c.quota && typeof c.quota === 'object') ? c.quota : {};
const changes = {
  keywords_id: strArr(c.keywords_id, 12),
  hook_style: String(c.hook_style || '').slice(0, 80),
  tone: String(c.tone || '').slice(0, 120),
  min_score: clamp(c.min_score, 50, 95, Number($env.AI_GATE_MIN || 70)),
  quota: {
    id: clamp(q.id, 0, 6, Number($env.POSTS_PER_DAY_ID || 3)),
    en: clamp(q.en, 0, 4, Number($env.POSTS_PER_DAY_EN || 2))
  }
};
const diagnosis = String(s.diagnosis || '').slice(0, 800);
const expected = String(s.expected_impact || '').slice(0, 400);
let analysis = String(s.analysis || '').slice(0, 1500);
if (diagnosis) analysis += '\nDIAGNOSA: ' + diagnosis;
if (expected) analysis += '\nDAMPAK DIHARAPKAN: ' + expected;
const severity = ['decline', 'weekly', 'normal'].includes(String(s.severity || '').toLowerCase())
  ? String(s.severity || '').toLowerCase() : 'weekly';
return {
  json: {
    skip: false,
    severity,
    analysis,
    diagnosis,
    expected_impact: expected,
    keep: strArr(s.keep, 10),
    stop: strArr(s.stop, 10),
    changes,
    hypotheses: strArr(s.hypotheses, 5),
    health: clamp(s.health, 0, 100, 50)
  }
};

