WITH deactivated AS (
  UPDATE strategy SET active = false WHERE active = true
)
INSERT INTO strategy (version, analysis, changes, hypotheses, health_score, active)
VALUES (
  (SELECT COALESCE(MAX(version), 0) + 1 FROM strategy),
  $1::jsonb, $2::jsonb, $3::jsonb, $4, true
)
RETURNING id, version;
